    /**
     * @method
     * @name interactivebrokers#fetchMarkets
     * @description retrieves data on the market types of options.fetchMarkets.types: stocks of options.fetchMarkets.exchanges.STK, crypto of options.fetchMarkets.cryptoSpotSymbols, fx pairs of options.fetchMarkets.forexCurrencies, coinbase derivatives perp-style futures discovered with the market scanner (as swap, e.g. BTC/USD:USD), dated coinbase derivatives futures (scanned) and CME and CFE crypto futures of options.fetchMarkets.cryptoCmeFutureSymbols (as future, e.g. BTC/USD:USD-261127) and cfds of options.fetchMarkets.cfdExchanges (as swap, e.g. AAPL/USD:USD), bonds of options.fetchMarkets.bondSymbols are loaded only with 'bond' in options.fetchMarkets.types (as spot, e.g. US-T-4.125-270131.SMART/USD), the market id is the IBKR conid
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-conids-by-exchange
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-bond-filters
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-info-and-rules
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-future-by-symbol
     * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-contract-symbols-from-body
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-currency-pairs
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-instrument-definition
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<List<Object>> fetchMarkets(Map<String, Object> parameters)
    {
        return BaseExchange.supplyAsync(() -> this.fetchMarketsCore(parameters)).thenApply(res -> (List<Object>) res);
    }

    private Object fetchMarketsCore(Map<String, Object> parameters)
    {

        Map<String, Object> options = this.safeDict(this.options, "fetchMarkets", new HashMap<String, Object>() {{}});
        List<Object> types = this.safeList(options, "types", new ArrayList<Object>(Arrays.asList()));
        List<CompletableFuture<?>> promises = new ArrayList<CompletableFuture<?>>();
        // the order matters, on symbol collisions the earlier contract keeps the plain symbol
        if (this.inArray("stock", types))
        {
            promises.add(this.fetchStockMarkets(parameters));
        }
        if (this.inArray("crypto", types))
        {
            promises.add(this.fetchCryptoMarkets(parameters));
        }
        if (this.inArray("forex", types))
        {
            promises.add(this.fetchForexMarkets(parameters));
        }
        if (this.inArray("swap", types) || this.inArray("future", types))
        {
            // the swaps and the futures come from the same scans and requests
            promises.add(this.fetchFuturesAndSwapMarkets(parameters));
        }
        if (this.inArray("cfd", types))
        {
            promises.add(this.fetchCfdMarkets(parameters));
        }
        if (this.inArray("bond", types))
        {
            promises.add(this.fetchBondMarkets(parameters));
        }
        List<Object> results = (CompletableFuture.allOf(promises.toArray(new CompletableFuture<?>[0])).thenApply((promiseAllDone) -> new ArrayList<Object>(promises.stream().<Object>map(CompletableFuture::join).toList()))).join();
        List<Object> markets = this.arraysConcat(results);
        // toArray is the identity on a list, it types the result as a list for the statically typed ports
        return this.toArray(this.ibkrDisambiguateContractSymbols(markets));

    }

    /**
     * @method
     * @name interactivebrokers#ibkrDisambiguateContractSymbols
     * @description gives a unique symbol to the contract markets that share a symbol with an earlier market, e.g. the GRAYSCALE BITCOIN MINI ETF CFD (ticker BTC) and the BTC perp-style future both map to BTC/USD:USD, the cfd becomes BTC.IBUSCFD/USD:USD
     * @ignore
     * @param {object[]} markets parsed markets
     * @returns {object[]} the markets with unique symbols
     */
    public List<Object> ibkrDisambiguateContractSymbols(List<Object> markets)
    {
        Map<String, Object> seen = new HashMap<String, Object>() {{}};
        List<Object> result = new ArrayList<Object>(Arrays.asList());
        for (var i = 0; i < markets.size(); i++)
        {
            Map<String, Object> market = this.extend(new HashMap<String, Object>() {{}}, (markets == null || i < 0 || i >= markets.size() ? null : markets.get(i)));
            String symbol = this.safeString(market, "symbol");
            Boolean isContract = (Boolean) this.safeBool(market, "contract", false);
            if ((seen.containsKey(symbol)) && Boolean.TRUE.equals(isContract))
            {
                Map<String, Object> info = this.safeDict(market, "info", new HashMap<String, Object>() {{}});
                String listingExchange = this.safeString2(info, "listingExchange", "exchange", "default");
                String marketBase = this.safeString(market, "base", "");
                String marketBaseId = this.safeString(market, "baseId", "");
                Boolean isFuture = (Boolean) this.safeBool(market, "future", false);
                // keeps the quote, settle and the expiry suffix of futures, e.g. /USD:USD-261127
                List<Object> symbolParts = new ArrayList<Object>(Arrays.asList(((String)symbol).split(java.util.regex.Pattern.quote("/"))));
                String quotePart = this.safeString(symbolParts, 1, "");
                String quoteAndSettle = ("/" + quotePart);
                String base = ((marketBase + ".") + listingExchange);
                if (Boolean.TRUE.equals(isFuture) && (!java.util.Objects.equals(marketBaseId, marketBase)))
                {
                    // the futures of the same base and expiry (BRR, MBT, BFF) are told apart by the IBKR ticker, e.g. BTC.MBT/USD:USD-261127
                    base = ((marketBase + ".") + marketBaseId);
                }
                String newSymbol = (base + quoteAndSettle);
                if (seen.containsKey(newSymbol))
                {
                    String marketId = this.safeString(market, "id", "");
                    base = ((marketBase + ".") + marketId);
                    newSymbol = (base + quoteAndSettle);
                }
                HashMap<String, Object> mapLiteral1 = new HashMap<String, Object>();
                mapLiteral1.put("symbol", newSymbol);
                mapLiteral1.put("base", base);
                market = this.extend(market, mapLiteral1);
            }
            String finalSymbol = this.safeString(market, "symbol");
            seen.put(finalSymbol, true);
            ((List<Object>)result).add(market);
        }
        return result;
    }

    public CompletableFuture<Object> fetchSecWithDetails(Map<String, Object> plainEntries)
    {
        return BaseExchange.supplyAsync(() -> this.fetchSecWithDetailsCore(plainEntries));
    }

    private Object fetchSecWithDetailsCore(Map<String, Object> plainEntries)
    {

        List<String> detailIds = new ArrayList<String>(plainEntries.keySet());
        List<Object> entries = new ArrayList<Object>(Arrays.asList());
        Integer numDetails = detailIds.size();
        if (java.util.Objects.equals(numDetails, 0))
        {
            return entries;
        }
        Integer chunkSize = 330; // above this number, response becomes unreliable
        List<CompletableFuture<?>> promises = new ArrayList<CompletableFuture<?>>();
        Object offset = 0;
        while ((!(offset == null && numDetails == null) && offset == null || (numDetails != null && !(((Number) offset).doubleValue() >= numDetails))))
        {
            Object end = ((java.util.function.BinaryOperator<Object>) (j38a, j38b) -> { if (j38a == null || j38b == null) return null; java.util.function.ToDoubleFunction<Object> j38d = j38o -> { if (j38o instanceof Double || j38o instanceof Float || j38o instanceof Long || j38o instanceof Integer || j38o instanceof java.math.BigDecimal) return ((Number) j38o).doubleValue(); try { return Double.parseDouble(String.valueOf(j38o)); } catch (NumberFormatException j38x) { return 0.0; } }; double j38u = j38d.applyAsDouble(j38a); double j38v = j38d.applyAsDouble(j38b); return (j38u < j38v) ? j38a : j38b; }).apply(this.sum(offset, chunkSize), numDetails);
            List<String> chunk = new ArrayList<String>(Arrays.asList());
            for (long k = ((long) (switch ((Object) (offset)) { case null -> Long.parseLong("null"); case Long hx4J40v7 -> hx4J40v7.longValue(); case Integer hx4J40v7 -> hx4J40v7.longValue(); case Double hx4J40v7 -> hx4J40v7.longValue(); case Float hx4J40v7 -> hx4J40v7.longValue(); case java.math.BigDecimal hx4J40v7 -> hx4J40v7.longValue(); case String hx4J40v7 -> Long.parseLong(hx4J40v7); case Object hx4J40v7 -> Long.parseLong(String.valueOf(hx4J40v7)); })); ((end != null && !(k >= ((Number) end).doubleValue()))); k++)
            {
                String detailId = this.safeString(detailIds, k, "");
                chunk.add(detailId);
            }
            Map<String, Object> secdefRequest = new HashMap<String, Object>() {{
                put( "conids", String.join(",", (List<String>)chunk) );
            }};
            promises.add(this.marketsEndpointCall(secdefRequest, "webapiGetV1ApiTrsrvSecdef", new HashMap<String, Object>() {{}}));
            offset = end;
        }
        List<Object> responses = (CompletableFuture.allOf(promises.toArray(new CompletableFuture<?>[0])).thenApply((promiseAllDone) -> new ArrayList<Object>(promises.stream().<Object>map(CompletableFuture::join).toList()))).join();
        //
        //     {
        //         "secdef": [
        //             {
        //                 "conid": 479624278,
        //                 "currency": "USD",
        //                 "incrementRules": [ { "lowerEdge": 0, "increment": 0.25 } ],
        //                 "listingExchange": "PAXOS",
        //                 "assetClass": "CRYPTO",
        //                 "ticker": "BTC",
        //                 ...
        //             }
        //         ]
        //     }
        //
        for (var i = 0; i < responses.size(); i++)
        {
            List<Object> secdefs = this.safeList((responses == null || i < 0 || i >= responses.size() ? null : responses.get(i)), "secdef", new ArrayList<Object>(Arrays.asList()));
            for (var j = 0; j < secdefs.size(); j++)
            {
                Object secdef = (secdefs == null || j < 0 || j >= secdefs.size() ? null : secdefs.get(j));
                String conid = this.safeString(secdef, "conid", "");
                Map<String, Object> entry = this.safeDict(plainEntries, conid, null);
                ((List<Object>)entries).add(this.extend(entry, secdef));
            }
        }
        return entries;

    }

