    public String ibkrParseValue(String value)
    {
        // snapshot values are formatted strings: "C82838.50" (prior close), "H1.2" (halted), "+1.04", "1.5%", "1M", "1,234", "$11,000K" (bond sizes, the principal amount)
        if ((java.util.Objects.equals(value, null)) || (java.util.Objects.equals(value, "")) || (java.util.Objects.equals(value, "N/A")))
        {
            return null;
        }
        List<String> valueParts = new ArrayList<String>(Arrays.asList(((String)value).split(java.util.regex.Pattern.quote(","))));
        Object result = String.join("", valueParts);
        if (((String)result).startsWith("C") || ((String)result).startsWith("H") || ((String)result).startsWith("+") || ((String)result).startsWith("$"))
        {
            result = (result == null ? null : ((String)result).substring(Math.min(1, ((String)result).length())));
        }
        if (((String)result).endsWith("%"))
        {
            result = (result == null ? null : ((String)result).substring(0, (int) Math.min(((((long) ((String)result).length()) - 1L)) < 0 ? ((String)result).length() + ((((long) ((String)result).length()) - 1L)) : ((((long) ((String)result).length()) - 1L)), ((String)result).length())));
        }
        String multiplier = null;
        if (((String)result).endsWith("K"))
        {
            multiplier = "1000";
        } else if (((String)result).endsWith("M"))
        {
            multiplier = "1000000";
        } else if (((String)result).endsWith("B"))
        {
            multiplier = "1000000000";
        }
        if (!java.util.Objects.equals(multiplier, null))
        {
            return Precise.stringMul((result == null ? null : ((String)result).substring(0, (int) Math.min(((((long) ((String)result).length()) - 1L)) < 0 ? ((String)result).length() + ((((long) ((String)result).length()) - 1L)) : ((((long) ((String)result).length()) - 1L)), ((String)result).length()))), multiplier);
        }
        if (java.util.Objects.equals(result, ""))
        {
            return null;
        }
        return (String) (result);
    }

