    /**
     * @method
     * @name interactivebrokers#createOrderRequest
     * @description builds a single order ticket for createOrder and editOrder
     * @ignore
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type 'market' or 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much of currency you want to trade in units of base currency
     * @param {float} [price] the price at which the order is to be fulfilled
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the order ticket
     */
    public Map<String, Object> createOrderRequest(String symbol, String type, String side, Object amount, Object price, Map<String, Object> parameters)
    {
        Map<String, Object> market = this.market(symbol);
        Boolean isMarket = (java.util.Objects.equals(type, "market"));
        String triggerPrice = this.safeString2(parameters, "triggerPrice", "stopPrice");
        String trailingAmount = this.safeString(parameters, "trailingAmount");
        String trailingPercent = this.safeString(parameters, "trailingPercent");
        String clientOrderId = this.safeString2(parameters, "clientOrderId", "cOID");
        String assetClass = this.safeString(market.get("info"), "assetClass");
        Map<String, Object> request = new HashMap<String, Object>();
        request.put("conid", this.parseToInt(market.get("id")));
        request.put("side", ((String)side).toUpperCase());
        // a market order with params['cost'] is sent by cost (cashQty) without a quantity
        String cost = this.safeString2(parameters, "cost", "cashQty");
        Boolean isMarketByCost = Boolean.TRUE.equals(isMarket) && (!java.util.Objects.equals(cost, null));
        if (!Boolean.TRUE.equals(isMarketByCost))
        {
            request.put("quantity", this.parseNumber(this.amountToPrecision(symbol, amount)));
        }
        String orderType = null;
        if ((!java.util.Objects.equals(trailingAmount, null)) || (!java.util.Objects.equals(trailingPercent, null)))
        {
            orderType = ((Boolean.TRUE.equals(isMarket))) ? "TRAIL" : "TRAILLMT";
            if (!java.util.Objects.equals(trailingPercent, null))
            {
                request.put("trailingType", "%");
                request.put("trailingAmt", this.parseNumber(trailingPercent));
            } else
            {
                request.put("trailingType", "amt");
                request.put("trailingAmt", this.parseNumber(this.priceToPrecision(symbol, trailingAmount)));
            }
            if (!java.util.Objects.equals(triggerPrice, null))
            {
                request.put("auxPrice", this.parseNumber(this.priceToPrecision(symbol, triggerPrice)));
            }
            if (!Boolean.TRUE.equals(isMarket))
            {
                request.put("price", this.parseNumber(this.priceToPrecision(symbol, price)));
            }
        } else if (!java.util.Objects.equals(triggerPrice, null))
        {
            if (Boolean.TRUE.equals(isMarket))
            {
                orderType = "STP";
                request.put("price", this.parseNumber(this.priceToPrecision(symbol, triggerPrice)));
            } else
            {
                orderType = "STP LMT";
                request.put("price", this.parseNumber(this.priceToPrecision(symbol, price)));
                request.put("auxPrice", this.parseNumber(this.priceToPrecision(symbol, triggerPrice)));
            }
        } else if (Boolean.TRUE.equals(isMarket))
        {
            orderType = "MKT";
            if (Boolean.TRUE.equals(isMarketByCost))
            {
                request.put("cashQty", this.parseNumber(this.priceToPrecision(symbol, cost)));
            } else if (java.util.Objects.equals(side, "buy"))
            {
                throw new InvalidOrder((this.id + " createOrder() requires params[\"cost\"] for market buy orders")) ;
            }
        } else
        {
            orderType = "LMT";
            request.put("price", this.parseNumber(this.priceToPrecision(symbol, price)));
        }
        request.put("orderType", orderType);
        String defaultTimeInForce = "DAY";
        if (java.util.Objects.equals(assetClass, "CRYPTO"))
        {
            defaultTimeInForce = ((Boolean.TRUE.equals(isMarket))) ? "IOC" : "GTC";
        }
        String timeInForce = this.safeStringUpper2(parameters, "timeInForce", "tif", defaultTimeInForce);
        request.put("tif", timeInForce);
        if (java.util.Objects.equals(clientOrderId, null))
        {
            clientOrderId = ("ccxt" + this.uuid22());
        }
        request.put("cOID", clientOrderId);
        Map<String, Object> query = this.omit(parameters, new ArrayList<Object>(Arrays.asList("triggerPrice", "stopPrice", "trailingAmount", "trailingPercent", "clientOrderId", "cOID", "timeInForce", "tif", "cost", "cashQty")));
        List<String> queryKeys = new ArrayList<String>(query.keySet());
        for (var i = 0; i < queryKeys.size(); i++)
        {
            String key = (queryKeys == null || i < 0 || i >= queryKeys.size() ? null : queryKeys.get(i));
            request.put(key, (query == null || key == null ? null : query.get(key)));
        }
        return request;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrHandleOrderReplies
     * @description confirms order reply prompts until the order is accepted, or throws InvalidOrder when options.createOrder.autoConfirmOrderReplies is false
     * @ignore
     * @param {object} response the order submission response
     * @param {string} methodName the calling method name
     * @returns {object} the accepted order entry
     */
    public CompletableFuture<Map<String, Object>> ibkrHandleOrderReplies(Object response, String methodName)
    {
        return BaseExchange.supplyAsync(() -> this.ibkrHandleOrderRepliesCore(response, methodName));
    }

    private Map<String, Object> ibkrHandleOrderRepliesCore(Object response, String methodName)
    {

        Map<String, Object> options = this.safeDict(this.options, "createOrder", new HashMap<String, Object>() {{}});
        Boolean autoConfirm = (Boolean) this.safeBool(options, "autoConfirmOrderReplies", true);
        Long maxReplies = this.safeInteger(options, "maxReplies", 10);
        String errorPrefix = (((this.id + " ") + methodName) + "() ");
        Object current = response;
        for (var i = 0; ((maxReplies != null && i <= maxReplies)); i++)
        {
            if (!(current instanceof List))
            {
                //
                // advanced order reject
                //
                //     { "orderId": 123456789, "reqId": "22170", "text": "...", "options": [ ... ], "messageId": "p12", "prompt": true }
                //
                String text = this.safeString(current, "text");
                throw new InvalidOrder(((errorPrefix + "rejected: ") + text)) ;
            }
            Map<String, Object> first = this.safeDict(current, 0, new HashMap<String, Object>() {{}});
            String orderId = this.safeString2(first, "order_id", "orderId");
            if (!java.util.Objects.equals(orderId, null))
            {
                return first;
            }
            //
            // reply prompt
            //
            //     [ { "id": "99097238-...", "isSuppressed": false, "message": [ "You are submitting an order without market data..." ], "messageIds": [ "o354" ] } ]
            //
            String replyId = this.safeString(first, "id");
            List<String> messages = (List<String>) this.safeList(first, "message", new ArrayList<Object>(Arrays.asList()));
            String message = String.join(" ", messages);
            if (java.util.Objects.equals(replyId, null))
            {
                throw new InvalidOrder(((errorPrefix + "unexpected response: ") + this.json(current))) ;
            }
            if (!Boolean.TRUE.equals(autoConfirm))
            {
                throw new InvalidOrder(((((errorPrefix + "requires confirmation (reply id ") + replyId) + "): ") + message)) ;
            }
            Map<String, Object> replyRequest = new HashMap<String, Object>();
            replyRequest.put("replyId", replyId);
            replyRequest.put("confirmed", true);
            current = (this.webapiPostV1ApiIserverReplyReplyId(replyRequest)).join();
        }
        throw new InvalidOrder((errorPrefix + "exceeded options.createOrder.maxReplies order reply confirmations")) ;

    }

