            //
            // pa/transactions
            //
            //    {
            //        "cur": "USD",
            //        "date": "Thu Oct 08 00:00:00 EDT 2026",
            //        "rawDate": "20261008",
            //        "fxRate": 1,
            //        "pr": 2417.9,
